<?php
namespace App\Controllers;
use App\Support\{Session,View,Request,Response,Database};use App\Services\Portal\PortalService;
final class PortalController { public function login():void{View::render('portal/login',['title'=>'Client Portal']);} public function authenticate():void{$r=new Request();$s=Database::pdo()->prepare('SELECT * FROM portal_users WHERE tenant_id=1 AND username=? AND is_active=1');$s->execute([$r->input('username')]);$u=$s->fetch();if(!$u||!password_verify((string)$r->input('password'),$u['password_hash'])){View::render('portal/login',['error'=>'Invalid portal credentials']);return;}session_regenerate_id(true);Session::set('portal_user_id',(int)$u['id']);Session::set('portal_client_id',(int)$u['client_id']);Response::redirect('/portal');} public function index():void{$id=Session::get('portal_client_id');if(!$id)Response::redirect('/portal/login');View::render('portal/index',(new PortalService)->clientSnapshot((int)$id));} public function logout():void{Session::set('portal_user_id',null);Session::set('portal_client_id',null);Response::redirect('/portal/login');}}
